            continue
        run = 1
        while r + run < h and [v for v in grid[r + run] if v != 0] == vals:
            run += 1
        if run >= 2:
            palette = vals
            palette_rows = set(range(r, r + run))
            break
    if palette is None or 1 not in palette:
        return grid

    # The template is the contiguous block of 1s outside the palette strip.
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] == 1 and r not in palette_rows]
    if not pts:
        return grid

    top = min(r for r, c in pts)
    bottom = max(r for r, c in pts)
    left = min(c for r, c in pts)
    shape = {(r - top, c - left) for r, c in pts}
    tile_h = bottom - top + 1

    out = [[0] * w for _ in range(h)]
    first_top = top - palette.index(1) * tile_h
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr, cc = first_top + i * tile_h + dr, left + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
